mod tests {
    use super::*;
    use octocrab::models::repos::{Content, ContentLinks};

    fn sample_content(path: &str, r#type: &str, size: i64) -> Content {
        Content {
            name: path.rsplit('/').next().unwrap_or(path).to_string(),
            path: path.to_string(),
            sha: "deadbeef".into(),
            encoding: Some("base64".into()),
            content: None,
            size,
            url: "https://api.github.com/content".into(),
            html_url: None,
            git_url: None,
            download_url: None,
            r#type: r#type.into(),
            links: ContentLinks {
                git: None,
                html: None,
                _self: "https://api.github.com/content".parse().unwrap(),
            },
            license: None,
        }
    }

    #[test]
    fn expect_single_file_rejects_empty() {
        let err = expect_single_file(vec![], "skills/x/SKILL.md")
            .expect_err("empty items should error");
        assert!(err.to_string().contains("No content"));
    }

    #[test]
    fn expect_single_file_rejects_multiple() {
        let path = "skills/x/SKILL.md";
        let err = expect_single_file(
            vec![sample_content(path, "file", 1), sample_content(path, "file", 1)],
            path,
        )
        .expect_err("multiple items should error");
        assert!(err.to_string().contains("expected exactly 1"));
    }

    #[test]
    fn expect_single_file_rejects_non_file() {
        let path = "skills/x/SKILL.md";
        let err = expect_single_file(vec![sample_content(path, "dir", 0)], path)
            .expect_err("non-file should error");
        assert!(err.to_string().contains("expected a file"));
    }

    #[test]
    fn expect_single_file_rejects_path_mismatch() {
        let err = expect_single_file(
            vec![sample_content("skills/other/SKILL.md", "file", 1)],
            "skills/x/SKILL.md",
        )
        .expect_err("path mismatch should error");
        assert!(err.to_string().contains("path mismatch"));
    }

    #[test]
    fn expect_single_file_accepts_exact_file() {
        let path = "skills/x/SKILL.md";
        let item = expect_single_file(vec![sample_content(path, "file", 5)], path)
            .expect("single file should succeed");
        assert_eq!(item.path, path);
        assert_eq!(item.r#type, "file");
    }

    #[test]
    fn bytes_to_skill_content_rejects_empty() {
        let path = "skills/x/SKILL.md";
        let item = sample_content(path, "file", 0);
        let err = bytes_to_skill_content(&item, Vec::new(), path)
            .expect_err("empty bytes should error");
        assert!(err.to_string().contains("empty"));
    }

    #[test]
    fn bytes_to_skill_content_rejects_size_mismatch() {
        let path = "skills/x/SKILL.md";
        let item = sample_content(path, "file", 99);
        let err = bytes_to_skill_content(&item, b"hello".to_vec(), path)
            .expect_err("size mismatch should error");
        assert!(err.to_string().contains("size"));
    }

    #[test]
    fn bytes_to_skill_content_builds_skill() {
        let path = "skills/my-skill/SKILL.md";
        let item = sample_content(path, "file", 5);
        let skill = bytes_to_skill_content(&item, b"hello".to_vec(), path)
            .expect("valid bytes should succeed");
        assert_eq!(skill.name, "my-skill");
        assert_eq!(skill.content, "hello");
        assert_eq!(skill.sha, "deadbeef");
        assert_eq!(skill.size, 5);
        assert_eq!(skill.encoding.as_deref(), Some("base64"));
    }

    #[test]
    fn decodes_base64_content_stripping_whitespace() {
        // "hello" base64-encoded, with GitHub-style embedded newlines.
        let bytes = decode_github_content(Some("base64"), "aGVs\nbG8=\n", "skills/x/SKILL.md")
            .expect("should decode");
        assert_eq!(bytes, b"hello");
    }

    #[test]
    fn rejects_non_base64_encoding() {
        // Large files come back with `encoding: "none"` and empty content;
        // this must error instead of silently producing an empty skill.
        let err = decode_github_content(Some("none"), "", "skills/x/SKILL.md")
            .expect_err("non-base64 encoding should error");
        assert!(err.to_string().contains("Unsupported content encoding"));
    }

    #[test]
    fn rejects_missing_encoding() {
        assert!(decode_github_content(None, "", "skills/x/SKILL.md").is_err());
    }

    #[test]
    fn extracts_skill_name_from_path() {
        assert_eq!(
            extract_skill_name("skills/my-skill/SKILL.md").unwrap(),
            "my-skill"
        );
    }

    #[test]
    fn extracts_skill_name_strips_only_one_suffix() {
        // `trim_end_matches` would strip both segments; `strip_suffix` strips one.
        assert_eq!(
            extract_skill_name("skills/SKILL.md/SKILL.md").unwrap(),
            "SKILL.md"
        );
    }

    #[test]
    fn extract_skill_name_rejects_empty_component() {
        assert!(extract_skill_name("/SKILL.md").is_err());
    }
