/// Downloads file content from GitHub using the octocrab client.
/// The GitHub contents API returns base64-encoded content, which is decoded here.
async fn fetch_from_github(
    client: &octocrab::Octocrab,
    owner: &str,
    repo: &str,
    path: &str,
) -> Result<SkillContent> {
    debug!(
        "Fetching file content from GitHub: owner = {}, repo = {}, path = {}",
        owner, repo, path
    );

    let response = client
        .repos(owner, repo)
        .get_content()
        .path(path)
        .send()
        .await
        .context("Failed to fetch file from GitHub")?;
    debug!("GitHub response: {:?}", response);

    let item = expect_single_file(response.items, path)?;
    let encoded = item
        .content
        .as_deref()
        .context("No content field in GitHub response")?;
    let bytes = decode_github_content(item.encoding.as_deref(), encoded, path)?;
    bytes_to_skill_content(&item, bytes, path)
}

/// Ensures the Contents API returned exactly one file at `path`.
fn expect_single_file(
    items: Vec<octocrab::models::repos::Content>,
    path: &str,
) -> Result<octocrab::models::repos::Content> {
    let item = match <[_; 1]>::try_from(items) {
        Ok([item]) => item,
        Err(items) if items.is_empty() => bail!("No content returned from GitHub"),
        Err(items) => bail!(
            "GitHub returned {} items for a single file path; expected exactly 1",
            items.len()
        ),
    };
    if item.r#type != "file" {
        bail!(
            "GitHub returned a '{}' at '{}', expected a file",
            item.r#type,
            path
        );
    }
    if item.path != path {
        bail!(
            "GitHub path mismatch for `{}`: response path was `{}`",
            path,
            item.path
        );
    }
    Ok(item)
}

/// Builds `SkillContent` after validating decoded bytes against Contents metadata.
fn bytes_to_skill_content(
    item: &octocrab::models::repos::Content,
    bytes: Vec<u8>,
    path: &str,
) -> Result<SkillContent> {
    if bytes.is_empty() {
        bail!("GitHub returned empty file content for `{}`", path);
    }

    let size = usize::try_from(item.size)
        .with_context(|| format!("GitHub returned an invalid (negative) size for `{}`", path))?;
    if bytes.len() != size {
        bail!(
            "GitHub size mismatch for `{}`: decoded {} bytes, metadata size {}",
            path,
            bytes.len(),
            size
        );
    }

    let name = extract_skill_name(&item.path)?;
    validate_skill_name(&name)?;

    Ok(SkillContent {
        name,
        content: String::from_utf8(bytes).context("File content is not valid UTF-8")?,
        sha: item.sha.clone(),
        encoding: item.encoding.clone(),
        size,
    })
}

